#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_blendFactor;
uniform float amzp_scanlineHeight;
uniform float amzp_scanlineIntensity;
uniform float amzp_scrollSpeed;
uniform float amzp_scanAngle;
layout(color) uniform half4 amzp_scanColor;
uniform float amzp_progress;
uniform float amzp_grainIntensity;
uniform float amzp_grainTimeScale;
uniform float amzp_glitchProbability;
uniform float amzp_glitchIntensityX;
uniform float amzp_glitchIntensityY;
uniform float amzp_glitchPhase;
uniform float amzp_bandSpeed;
uniform float amzp_bandHeight;
uniform float amzp_bandIntensity;
uniform float amzp_bandChoppiness;
uniform float amzp_staticAmount;
uniform float amzp_warpFactor;
uniform float amzp_chromaAmount;
uniform float amzp_bandPos;


        float hash12(float2 p) {
            return fract(sin(dot(p, float2(12.9898,78.233))) * 43758.5453);
        }

        void amzRender() {
            float2 res = screen.zw;
            float2 uv  = amzScreenNorm();


            float ang = radians(amzp_scanAngle);
            float2 dir = float2(cos(ang), sin(ang));
            float scanCoord = dot(uv * res, dir);

            float scanline = sin((scanCoord - amzp_progress * amzp_scrollSpeed) / max(amzp_scanlineHeight, 1.0));
            float3 vhsColor = amzp_scanColor.rgb * scanline * amzp_scanlineIntensity;


            float2 grainSeed = float2(12.9898, 78.233) + amzp_progress * amzp_grainTimeScale;
            float grain = fract(sin(dot((uv * res) * uv, grainSeed)) * 43758.5453);
            vhsColor += float3(grain) * amzp_grainIntensity;


            float2 tuv = uv;
            if (amzp_glitchPhase < amzp_glitchProbability) {
                float gx = (fract(sin(amzp_progress * 12.9898) * 43758.5453) - 0.5) * amzp_glitchIntensityX;
                float gy = (fract(cos(amzp_progress * 78.233) * 43758.5453) - 0.5) * amzp_glitchIntensityY;
                tuv += float2(gx, gy);
            }


            float bandNoise = hash12(uv * res);
            float3 chromaColor = amzTexture(0, tuv).rgb;

            if (abs(uv.y - amzp_bandPos) < amzp_bandHeight) {
                float rs = bandNoise * amzp_bandChoppiness;
                vhsColor += float3(rs) * amzp_staticAmount;

                tuv.x += sin(uv.y * res.y * 10.0 + rs) * amzp_warpFactor;

                chromaColor = float3(
                    amzTexture(0, tuv + float2(amzp_chromaAmount * rs, 0.0)).r,
                    amzTexture(0, tuv).g,
                    amzTexture(0, tuv - float2(amzp_chromaAmount * rs, 0.0)).b
                );

                vhsColor = mix(vhsColor, chromaColor, amzp_bandIntensity * (1.0 - rs));
            }

            float3 originalColor = amzTexture(0, tuv).rgb;
            amzOutput = float4(mix(originalColor, vhsColor, amzp_blendFactor), 1.0);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

